class Iterator {
    struct Data {
        vector<int> nums;
        int idx;
    };
    Data* data;
public:
    Iterator(const vector<int>& nums) {
        data = new Data();
        data->nums = nums;
        data->idx = 0;
    }
    Iterator(const Iterator& iter) {
        data = new Data(*iter.data);
    }
    ~Iterator() { delete data; }
    int next() { return data->nums[data->idx++]; }
    bool hasNext() const { return data->idx < (int)data->nums.size(); }
};

class PeekingIterator : public Iterator {
public:
	PeekingIterator(const vector<int>& nums) : Iterator(nums) {
	    has_peeked = false;
	}

    // Returns the next element in the iteration without advancing the iterator.
	int peek() {
        if (!has_peeked) {
            peeked_value = Iterator::next();
            has_peeked = true;
        }
        return peeked_value;
	}

	// hasNext() and next() should behave the same as in the Iterator interface.
	// Override them if needed.
	int next() {
        if (has_peeked) {
            has_peeked = false;
            return peeked_value;
        }
        return Iterator::next();
	}

	bool hasNext() const {
        return has_peeked || Iterator::hasNext();
	}

private:
    int peeked_value;
    bool has_peeked;
};
